    "m9d29e3f1fda4": "解锁后可查看完整工作流并复刻到你的空间",
    "mc9e6dc01603b": "复刻到我的空间",
    "m94785087d77b": "Skills 文档导航",
    "mbeef286e1e42": "返回画布",
    "ma1244ebf6f97": "Banana Canvas Skills 知识库",
    "m811eed411af1": "给 Codex、Claude Code、WorkBuddy、OpenClaw、Hermes 以及其他支持 Skills 调用的智能体使用。",
    "m7ad916b385e7": "快速跳转",
    "m334c20e1a480": "快速开始",
    "m2ee1545f56ea": "最省事的安装方式是在画布右上角打开 Skills，创建 API Key，然后复制“安装提示词”给你的智能体。 智能体安装后应先调用模型列表接口验证 key，再根据用户需求选择图片、视频、音频、上传或写回流程。",
    "m6f3b8275a8be": "打开画布右上角 Skills。",
    "m8bc7205567e0": "复制安装提示词，交给 Codex、Claude Code、WorkBuddy、OpenClaw、Hermes 或其他支持 Skills 调用的智能体。",
    "m3aebf00d9c60": "智能体只调用当前站点下的",
    "med4fdf62488b": "，请求头使用",
    "m38a4b6027d11": "用户提供本地图片、视频或声音克隆参考音频时，先走 COS CDN 直传，再把返回的 URL 传给生成接口。",
    "m5fd644fb78c7": "给智能体的一次性提示",
    "m6c20b954bf44": "安装 Skill",
    "mfc872e6ee4bf": "推荐让智能体创建名为",
    "mfe6e0aad9757": "的 Skill，并把站点域名、API Key、可用端点、上传规则和轮询规则写进 Skill 正文。 如果运行环境不支持持久化 Skill，也可以直接按同样规则执行一次性指令。",
    "mcf6d961fe777": "安装后第一步必须调用",
    "m72aa6d301164": "。如果这个请求失败，不要继续生成任务，应要求用户重新复制或重置 API Key。",
    "m212c530be048": "环境变量方式",
    "m1e144659f89c": "认证与域名",
    "mcaf01b7201f2": "Skills API 使用用户在画布中创建的",
    "mf462d7922bc9": "key。智能体不需要浏览器会话，也不需要额外管理后台配置。 所有请求都应发往当前 docs 所在站点的 HTTPS 域名，并保持",
    "m67c8e6ed4170": "基础请求格式",
    "m2946ca7cb41d": "本地文件上传",
    "ma89cba08de24": "图片生成和视频生成接口接收 URL，不接收本地文件路径或原始字节。用户上传本地图片或视频时，智能体应先申请一次性上传地址， 把文件直接 PUT 到腾讯云 COS CDN 存储，再把返回的",
    "me28a42931f35": "用作图片",
    "m95691d962c7b": "、视频",
    "ma2123d69506f": "或",
    "mbd26d44fc6f3": "。 声音克隆参考文件使用",
    "m3f0104432871": "，单文件最大 100 MB。 上传只负责存储，不代表图片已经通过视频供应商审核。",
    "m653b123c956d": "调用",
    "mdb860ba6fd03": "，传入文件名、MIME、字节大小和媒体类型。",
    "m1ca9bf50f7bc": "使用返回的",
    "m2dbb717fb0d3": "直接上传文件字节。",
    "m234fc5d0ce24": "上传成功后，只把",
    "maea6cce83a21": "传给模型接口，不要询问或暴露对象存储 AK/SK。",
    "m95553d1a6b8e": "申请并使用 COS CDN 直传地址",
    "mbad945378028": "模型列表返回当前用户可用的图片、视频和音频模型。音频模型通过",
    "m0231bd78c443": "区分",
    "m3d7114281f5b": "和",
    "m2b82d2d0de33": "。智能体应优先使用返回的",
    "madd1a43ee3e9": "， 并避开不可用或需要额外套餐的模型。",
    "m6e18b7346f13": "读取可用模型",
    "m0ece727c3282": "图片接口同时支持文生图和图生图。文生图只传",
    "mcf88543a13be": "；图生图把一个或多个可访问图片 URL 放入",
    "mbfcdaeab0e24": "。 常用参数包括",
    "ma3be65d4e962": "和可选",
    "m921b7f191cab": "图生图请求",
    "m0e5841be535a": "视频接口用于文生视频、图生视频、视频参考和多素材工作流。图片或视频素材都必须是可访问 URL； 本地素材先通过上传流程转换成",
    "m9bf206b91387": "，再放进",
    "m9782952ede31": "。 服务端会根据当前租户渠道自动选择视频模式并执行必要的图片过审，智能体只需要调用统一 Skills 视频端点。 视频请求阶段会按该 Skills Key 所属租户和锁定渠道自动过审，不会故障转移到其他渠道；过审失败或超时会停止视频提交。 先读取",
    "m886a9cdf2da8": "中视频模型的",
    "ma27efc2cbc6c": "：9000 端口的租户管理后台只是配置入口，不能把端口或模型名硬编码成“必审模型”。 只有请求带图片且锁定渠道与当前租户的审图渠道严格匹配时才会过审；审图结果只对该锁定渠道有效，智能体无需也不应直接调用供应商过审接口。",
    "mae6ba72e3f23": "可省略；明确需要细分能力时，可传 Seedance 2.0 的",
    "me9cbdc278c79": "或 Kling v3 Omni 的",
    "mbcda964eb3f1": "等子模式。",
    "m7ed2ed2bde4d": "视频生成请求",
    "m22dc318dbe0f": "音频接口统一接入音色设计、声音克隆和 TTS 语音合成。先从",
    "m8af2350cfd65": "的",
    "meea50f4175bf": "按",
    "m75b23637c80a": "选择模型：音色设计传",
    "mde1d5dd076fb": "与",
    "m5aa750148a1a": "， 声音克隆传",
    "m1e055fccd727": "（或",
    "m0cc486559160": "），TTS 传",
    "m7f4ebe4ba68e": "， 也可以用",
    "mcab3911dfb7f": "直接合成。 任务必须轮询统一任务接口；只有真实音频下载并存储成功后才扣积分，失败和 30 分钟超时不扣费。 需要回写画布音频节点时，在请求中加入",
    "m847cc897cf41": "音色设计、声音克隆与 TTS",
    "m5293d4ba41fa": "生成接口通常返回任务 ID。智能体应轮询",
    "m6fc7ea2a3912": "，直到状态进入",
    "m039fe48058cb": "等终态，再把结果 URL 或错误说明返回给用户。",
    "m30acc3ecc74b": "轮询任务状态",
    "mf7e971a1e128": "当用户明确要求把结果写回已有画布节点时，生成请求可携带",
    "m729d327b06c2": "。 目前推荐",
    "mf79eade3afe4": "，它只替换目标节点的输出，不改变其他画布结构。",
    "m7458f19c733e": "写回已有画布节点",
    "m455be382d5d4": "计费与空间",
    "mbd295a4038a4": "Skills API 不绕过积分、团队空间或模型套餐规则。个人空间可省略空间参数；团队空间任务应传入",
    "mbfa48c649732": "和对应",
    "m032c41fcdb4c": "。如果接口返回套餐或余额错误，智能体应停止重试并把原因告诉用户。",
    "mab8f33d375d6": "团队空间上下文",
    "md4c908b6f8a9": "错误处理",
    "m533d81ad7f55": "智能体应把错误码翻译成用户能执行的下一步。认证、模型套餐、积分、权限、任务不存在这几类错误不要盲目重试。",
    "ma38a95717057": "API Key 缺失、格式错误或不匹配。让用户回到画布 Skills 面板复制新 key。",
