    m899b77da6243: "{value1}：{value2}。已完成项保留，可稍后重试缺项。",
    m41267fc849a5: "阿莱35-III型电影摄影机，好莱坞黄金年代主力机型。采用PL卡口，支持4齿孔/3齿孔走片，最高速度40fps。代表作：《星球大战》三部曲、《夺宝奇兵》系列、《E.T.外星人》。",
    md0381d45eeed: "阿莱435型高速电影摄影机，可变帧率1-150fps，配备电子快门角度调节(11.2°-180°)。广告、MV和高速摄影首选。代表作：《角斗士》高速战斗场景、《黑客帝国》子弹时间、《珍珠港》空战镜头。",
    m45b7466e889b: "阿莱535B型静音电影摄影机，工作室级静音设计(<20dB)，支持同步录音。内置精密注册销系统确保画面稳定。代表作：《辛德勒的名单》、《肖申克的救赎》、《阿甘正传》、《英国病人》。",
    m4c9830c68c83: "阿莱LT型轻便电影摄影机(Lite)，重量仅5.6kg，专为手持和斯坦尼康设计。支持1-60fps可变帧率。代表作：《谍影重重》三部曲手持镜头、《拆弹部队》、《黑暗骑士》部分场景。",
    me79f12362944: "阿莱ST型工作室电影摄影机(Studio)，ARRI最后的35mm胶片机巅峰之作。超静音设计，4齿孔精密走片机构。代表作：《指环王》三部曲、《特洛伊》、《无间道风云》、《老无所依》。",
    m120cce5b3470: "阿莱16SR3型16毫米电影摄影机，16mm胶片机标杆。支持Super 16格式，可后期放大至35mm。纪录片和独立电影首选。代表作：《摔跤手》、《黑天鹅》、《月升王国》、BBC纪录片。",
    m430544312931: "潘那维申金色II型电影摄影机，好莱坞经典主力机型，超静音马达设计。代表作：《泰坦尼克号》、《勇敢的心》、《拯救大兵瑞恩》、《绿里奇迹》。90年代好莱坞大片标配。",
    m40cc1577dc2c: "潘那维申千禧年型电影摄影机，21世纪初好莱坞顶级胶片机。改进的画面注册系统，支持3-perf省胶片模式。代表作：《黑客帝国2&3》、《蜘蛛侠》三部曲、《金刚》(2005)。",
    m4e1ac0cde220: "潘那维申千禧年XL型轻便电影摄影机，超轻量设计(6.8kg机身)，手持拍摄革命。代表作：《断背山》、《老无所依》、《血色将至》，李安和科恩兄弟最爱。",
    me1137196e52e: "潘那维申千禧年XL2型电影摄影机，最后的顶级35mm胶片机。数字化辅助系统，精密3-perf走片。代表作：《盗梦空间》、《星际穿越》(部分)、《敦刻尔克》(35mm部分)、《八恶人》。",
    me122b3c76126: "穆维康紧凑型电影摄影机，奥地利精密制造，紧凑型胶片机先驱。被ARRI收购后技术融入Arricam系列。代表作：《辛德勒的名单》(部分)、《英国病人》、欧洲艺术电影。",
    m6e28b833deca: "穆维康超级美洲型电影摄影机，Moviecam旗舰产品，高速拍摄能力达120fps。精密工程和优秀的画面稳定性。代表作：《勇敢的心》(部分)、90年代欧洲电影节获奖作品。",
    maf9aa6ea74cb: "雅通XTR制作型16毫米摄影机，法国精密制造，纪录片界传奇机型。独特的\"猫在肩膀\"人体工程学设计。代表作：《华氏911》、《难以忽视的真相》、大量奥斯卡最佳纪录片。",
    m8ec47f902691: "雅通35-III型电影摄影机，Aaton 35mm旗舰，独特人体工程学设计让摄影师更舒适。代表作：法国和欧洲艺术电影、戛纳电影节获奖作品。",
    m94f153e6681e: "雅通佩内洛普型电影摄影机，最后的Aaton 35mm胶片机，配备数字取景器，胶片与数字的桥梁产品。代表作：《艺术家》、独立艺术电影。",
    mccef820d48f8: "米切尔BNCR型电影摄影机，好莱坞黄金年代工作室标准，精密注册销系统确保画面稳定。代表作：《教父》三部曲、《唐人街》、《飞越疯人院》、《出租车司机》。",
    mba62143e727d: "艾克莱尔NPR型16毫米摄影机(Noiseless Portable Reflex)，法国新浪潮运动神器，手持电影革命开创者。轻便静音设计改变了电影拍摄方式。代表作：法国新浪潮电影、《筋疲力尽》风格作品。",
    me69e2f851dd8: "博莱克斯H16反光取景摄影机，瑞士精密制造，发条驱动16mm机。实验电影和电影学院首选。代表作：斯坦·布拉哈格实验电影、无数学生作品、独立短片。",
    m06f8c795110f: "贝尔豪威尔2709型电影摄影机，好莱坞默片时代标准机型，历史传奇。精密金属机身，手摇驱动。代表作：《一个国家的诞生》、《党同伐异》、卓别林早期电影。",
    m195c2ee9ec1a: "潘那维申65系统大画幅摄影机，65mm大画幅胶片机，史诗巨制专用。70mm放映时画质惊人。代表作：《指环王》三部曲部分镜头、《大师》70mm版、《八恶人》70mm版。",
    mc25a183f4855: "IMAX MSM 9802型巨幕摄影机，15齿孔横向走片，人类最大胶片画幅。单卷胶片仅能拍摄3分钟。代表作：《敦刻尔克》IMAX场景、《星际穿越》IMAX场景、《信条》、《奥本海默》。",
